func (s *Server) userInfo(w http.ResponseWriter, r *http.Request) {
	// Each of the four lookups below can fail for two unrelated reasons: the
	// thing it looked for is gone, which is a fact about the token, or the
	// lookup itself did not complete, which is a fact about this service. All
	// four used to report both as invalid_token — the answer that tells the
	// relying party to throw the credential away and sign the person out. So a
	// database that stopped answering did not degrade this endpoint, it
	// invalidated every token in the Realm at once, and the fault said nothing
	// anywhere: 401 is the ordinary reply here, so the request counter and the
	// access log read as a quiet period of expired tokens.
	//
	// That distinction was already drawn twice in this file — for the Roles
	// below and, differently, for introspection — and these were the calls in
	// front of both, so a fault reached them first and the later care never ran.
	realm, err := s.realmFromPath(r)
	if err != nil {
		if !errors.Is(err, store.ErrNotFound) {
			s.writeUserInfoUnavailable(w, r, "realm", err)
			return
		}
		writeBearerError(w, "invalid_token")
		return
	}
	raw := bearerToken(r)
	// RFC 6750 §2.2: a POST may carry the token as the form field access_token
	// instead of the header, and some SDKs do. The route accepted POST already;
	// the token was read from the header alone, so a relying party using the
	// body was told its working token had expired. Only PostForm is consulted —
	// r.FormValue would also read the query string, and §2.3 is deliberately not
	// offered here (a token in the URL lands in every access log on the way).
	// GET reads no body at all.
	if r.Method == http.MethodPost {
		if err := r.ParseForm(); err != nil {
			writeOAuthError(w, http.StatusBadRequest, "invalid_request", "invalid form body")
			return
		}
		if fromBody := strings.TrimSpace(r.PostForm.Get("access_token")); fromBody != "" {
			// Naming the token twice is a malformed request (§2, "MUST NOT use
			// more than one method"), not a bad token — so it is 400, not the
			// 401 that tells the relying party to throw the credential away.
			if raw != "" {
				w.Header().Set("WWW-Authenticate", `Bearer error="invalid_request"`)
				writeOAuthError(w, http.StatusBadRequest, "invalid_request",
					"the access token was sent in both the Authorization header and the request body")
				return
			}
			raw = fromBody
		}
	}
	verified, err := s.oidc.Verify(r.Context(), realm, raw, "")
	// A token whose revocation state could not be read is unjudged, not bad:
	// the signature and the claims already checked out and only the "has this
	// been revoked" question is unanswered. Refusing is right; refusing as
	// invalid_token is not.
	if errors.Is(err, ressooidc.ErrTokenStateUnavailable) {
		s.writeUserInfoUnavailable(w, r, "revocation_state", err)
		return
	}
	if err != nil || verified.Extra.Type != "Bearer" {
		writeBearerError(w, "invalid_token")
		return
	}
	userID, err := uuid.Parse(verified.Claims.Subject)
	if err != nil {
		writeBearerError(w, "invalid_token")
		return
	}
	user, err := s.store.UserByID(r.Context(), userID)
	if err != nil && !errors.Is(err, store.ErrNotFound) {
		s.writeUserInfoUnavailable(w, r, "user", err)
		return
	}
	if err != nil || !user.Enabled {
		writeBearerError(w, "invalid_token")
		return
	}
	sid, parseErr := uuid.Parse(verified.Extra.SessionID)
	if parseErr != nil {
		writeBearerError(w, "invalid_token")
		return
	}
	if _, sessionErr := s.store.SessionAuthTime(r.Context(), sid); sessionErr != nil {
		if !errors.Is(sessionErr, store.ErrNotFound) {
			s.writeUserInfoUnavailable(w, r, "session", sessionErr)
			return
		}
		writeBearerError(w, "invalid_token")
		return
	}
	scopes := strings.Fields(verified.Extra.Scope)
	result := map[string]any{"sub": user.ID.String()}
	if slices.Contains(scopes, "profile") {
		result["preferred_username"] = user.Username
		result["name"] = user.DisplayName
	}
	if slices.Contains(scopes, "email") && user.Email != "" {
		result["email"] = user.Email
		result["email_verified"] = user.EmailVerified
	}
	if slices.Contains(scopes, "roles") {
		// Both errors used to be discarded, which turned a Role lookup that
		// failed into realm_access.roles: [] with a 200 beside it — the service
		// asserting that this person holds no Roles at all. That is not a
		// degraded answer, it is the wrong one, and it is indistinguishable
		// from an administrator having just taken every Role away. A relying
		// party reading these claims to decide what somebody may do therefore
		// demotes them for the length of the fault and restores them
		// afterwards, with nothing anywhere saying why.
		//
		// The same two calls behind the same scope already fail the request at
		// token issuance (internal/oidc.IssueUserTokens), so this endpoint was
		// the one place where an unreadable Role turned into a claim rather
		// than an error.
		roles, rolesErr := s.store.RealmRolesForUser(r.Context(), user.ID)
		if rolesErr != nil {
			s.writeUserInfoUnavailable(w, r, "realm_roles", rolesErr)
			return
		}
		clientRoles, clientRolesErr := s.store.ClientRolesForUser(r.Context(), user.ID)
		if clientRolesErr != nil {
			s.writeUserInfoUnavailable(w, r, "client_roles", clientRolesErr)
			return
		}
		result["realm_access"] = map[string]any{"roles": roles}
		resources := make(map[string]any, len(clientRoles))
		for clientID, assigned := range clientRoles {
			resources[clientID] = map[string]any{"roles": assigned}
		}
		result["resource_access"] = resources
	}
	writeJSON(w, http.StatusOK, result)
}

// writeUserInfoUnavailable refuses a userinfo request that could not be judged,
// instead of answering it with the part that worked or blaming the token.
//
// The status is deliberately 5xx rather than the 401 every other refusal here
// uses: the token is fine and the caller has nothing to fix, so telling it the
// token is invalid would have relying parties discard a working credential and
// sign people out over a fault on this side. It also keeps the failure visible
// in the request counter and the access log, which neither a 200 carrying half
// the claims nor a 401 among ordinary expiries would be.
//
// stage names which lookup failed, because from the outside every one of them
// produces the same response and only this line says which.
func (s *Server) writeUserInfoUnavailable(w http.ResponseWriter, r *http.Request, stage string, err error) {
	s.logger.Error("userinfo could not judge the request it was given", "trace_id", traceIDFrom(r.Context()),
		"realm", chi.URLParam(r, "realm"), "stage", stage, "error", err)
	writeOAuthError(w, http.StatusInternalServerError, "server_error", "the request could not be completed")
}

func (s *Server) introspect(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
	if err := r.ParseForm(); err != nil {
		writeOAuthError(w, http.StatusBadRequest, "invalid_request", "invalid form body")
		return
	}
	// The three lookups this endpoint makes before it reaches the two below
	// already had the same problem those were fixed for, and being in front of
	// them meant a fault arrived here first and the later care never ran: the
	// Realm, the revocation state, and the refresh-token table each answered
	// active=false whether they said no or failed to answer at all.
	realm, err := s.realmFromPath(r)
	if err != nil {
		s.recordUnjudgedIntrospection(r, "realm", err)
		writeJSON(w, http.StatusOK, map[string]any{"active": false})
		return
	}
	client, ok, err := s.authenticateOIDCClient(r, realm)
		}
	}
	s.audit(r, &realm.ID, nil, client.ClientID, "TOKEN_REVOKED", "SUCCESS", "client", client.ClientID, detail)
	w.WriteHeader(http.StatusOK)
}

func (s *Server) oidcLogout(w http.ResponseWriter, r *http.Request) {
	if r.Method == http.MethodPost {
		r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
		_ = r.ParseForm()
	}
	realm, err := s.realmFromPath(r)
	if err != nil {
		if s.realmLookupFailed(r, "logout", err) {
			// The session lookup further down already refuses this way and
			// audits a logout it could not carry out; answering 404 here ended
			// the request before either could happen, with the session still
			// alive and nothing in the trail.
			writeError(w, r, http.StatusInternalServerError, "internal_error", "요청을 처리하지 못했습니다.")
			return
		}
		writeError(w, r, http.StatusNotFound, "realm_not_found", "Realm을 찾을 수 없습니다.")
		return
	}
	values := r.URL.Query()
	if r.Method == http.MethodPost {
		values = r.Form
	}
	var client *domain.Client
	if hint := values.Get("id_token_hint"); hint != "" {
		// Enabled is tested in both branches. It was tested only in the one
		// below, so naming a switched-off Client by client_id was refused
		// while presenting its ID token was not — and what this Client
		// decides is whether a post-logout redirect target is allowed.
		//
		// Read as a hint rather than verified as a live token: this used to go
		// through Verify, which enforces expiry, and an expired ID token is the
		// ordinary thing a relying party has to hand at logout. Refusing it left
		// client nil, which dropped post_logout_redirect_uri without a word and
		// stranded the browser on this service's login page.
		if verified, verifyErr := s.oidc.IDTokenHint(r.Context(), realm, hint); verifyErr == nil {
			client = s.logoutClient(r, realm, verified.Extra.AuthorizedParty)
		}
	} else if identifier := values.Get("client_id"); identifier != "" {
		// RP-Initiated Logout 1.0 allows client_id in place of an
		// id_token_hint. The redirect target is still checked against the
		// client's registered list, so this cannot become an open redirect.
		client = s.logoutClient(r, realm, identifier)
	}
	redirectTo := ""
	if requested := values.Get("post_logout_redirect_uri"); requested != "" && client != nil && store.PostLogoutURIAllowed(*client, requested) {
		redirectTo = requested
	}
	session, sessionErr := s.store.SessionByToken(r.Context(), sessionCookie(r))
	switch {
	case sessionErr == nil && session.Session.RealmID == realm.ID:
		ended, detail := s.endSession(r, session.Session.ID)
		s.audit(r, &realm.ID, &session.User.ID, session.User.Username, "LOGOUT",
			partialIfNot(ended), "session", session.Session.ID.String(), detail)
	case sessionErr != nil && !errors.Is(sessionErr, store.ErrNotFound):
		// endSession says a logout that fails to revoke is the most misleading
		// failure this service has, and answers it with a PARTIAL entry naming
		// the session so an administrator can end it by hand. Failing to read
		// the session is the same outcome one step earlier — it stays live, the
		// relying parties holding refresh tokens bound to it go on renewing, no
		// back-channel logout is sent — and it reached here first, so none of
		// that care ran. There was no entry at all: the request looked exactly
		// like a logout from a browser that was not signed in, the cookies were
		// cleared, and the relying party was redirected to its post-logout page
		// as though everything had been ended.
		//
		// The session identifier is the one thing missing from the entry,
		// because reading it is what failed. The rest is the same shape, so a
		// trail already being watched for result=PARTIAL finds this too.
		s.logger.Error("logout could not read the session it was asked to end",
			"trace_id", traceIDFrom(r.Context()), "realm", realm.Name, "error", sessionErr)
		s.audit(r, &realm.ID, nil, "", "LOGOUT", "PARTIAL", "session", "",
			map[string]any{"session_revoked": false, "error": "look the session up: " + sessionErr.Error()})
	}
	s.clearBrowserCookies(w, r)
	if redirectTo != "" {
		parsed, _ := url.Parse(redirectTo)
		query := parsed.Query()
		if state := values.Get("state"); state != "" {
			query.Set("state", state)
		}
		parsed.RawQuery = query.Encode()
		http.Redirect(w, r, parsed.String(), http.StatusFound)
		return
	}
	if r.Method == http.MethodPost {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	http.Redirect(w, r, "/login?logged_out=1", http.StatusFound)
}

// logoutClient resolves the Client whose registered list decides whether a
// post-logout redirect target may be used, and reports nil when there is none
// to be had.
//
// A lookup that did not complete is not a Client that is absent, and both used
// to be the same silent nil. Unlike the authorization endpoint this one cannot
// turn the difference into an answer — the requested target has not been shown
// to belong to the caller, so there is nowhere safe to redirect an error, and
// the logout itself still has to be carried out — which is exactly why it has
// to be written down instead. Left unsaid, a clients table that stopped
// answering looks the same as a relying party naming a target it does not own:
// the browser is stranded on this service's page at the end of a logout that
// otherwise worked.
func (s *Server) logoutClient(r *http.Request, realm domain.Realm, identifier string) *domain.Client {
	found, err := s.store.ClientByIdentifier(r.Context(), realm.ID, identifier)
	if err != nil {
		if !errors.Is(err, store.ErrNotFound) {
			s.logger.Error("the client named at logout could not be looked up",
				"trace_id", traceIDFrom(r.Context()), "realm", realm.Name, "error", err)
		}
		return nil
	}
	// A switched-off Client decides nothing, so its registered targets are not
	// honoured either.
	if !found.Enabled {
		return nil
	}
	return &found
}

func bearerToken(r *http.Request) string {
	value := r.Header.Get("Authorization")
	if len(value) < 8 || !strings.EqualFold(value[:7], "Bearer ") {
		return ""
	}
	return strings.TrimSpace(value[7:])
}

